import{_ as s,o as n,c as e,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"22. 指针和地址","description":"The Little Book of C 中文版 — 22. 指针和地址","frontmatter":{"title":"22. 指针和地址","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","03-内存","中文"],"description":"The Little Book of C 中文版 — 22. 指针和地址","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":22,"sidebarWeight":22,"alternateZh":"/posts/c教程/zh-CN/03-内存/022-Pointers and Addresses","alternateEn":"/posts/c教程/en-US/03-Working with Memory/022-Pointers and Addresses"},"headers":[],"relativePath":"posts/c教程/zh-CN/03-内存/022-Pointers and Addresses.md","filePath":"posts/c教程/zh-CN/03-内存/022-Pointers and Addresses.md","lastUpdated":1790163617000}'),p={name:"posts/c教程/zh-CN/03-内存/022-Pointers and Addresses.md"};function i(o,a,l,d,c,r){return n(),e("div",null,[...a[0]||(a[0]=[t(`<p>[English version](/posts/c教程/en-US/03-Working with Memory/022-Pointers and Addresses)</p><p>指针是 C 编程的核心。它们使您能够直接访问内存，以及读取、写入和操作存储在程序中任何位置的数据的能力。了解指针会改变您对变量、函数和数据结构的看法。</p><p>如果不掌握指针，就无法真正掌握 C。</p><h4 id="什么是指针" tabindex="-1">什么是指针？ <a class="header-anchor" href="#什么是指针" aria-label="Permalink to &quot;什么是指针？&quot;">​</a></h4><p>指针是一个存储另一个变量地址的变量。将其视为对内存中特定位置的引用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int value = 42;</span></span>
<span class="line"><span>int *ptr = &amp;value; // pointer to int, stores the address of value</span></span></code></pre></div><p>-<code>&amp;value</code>给出内存地址<code>value</code>. -<code>ptr</code>持有该地址。 -<code>*ptr</code>允许您访问存储在那里的值（这称为取消引用）。</p><h4 id="小代码" tabindex="-1">小代码 <a class="header-anchor" href="#小代码" aria-label="Permalink to &quot;小代码&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int number = 10;</span></span>
<span class="line"><span>    int *p = &amp;number;  // pointer stores address of number</span></span>
<span class="line"><span>    printf(&quot;Value of number: %d\\n&quot;, number);</span></span>
<span class="line"><span>    printf(&quot;Address of number: %p\\n&quot;, (void *)&amp;number);</span></span>
<span class="line"><span>    printf(&quot;Pointer p holds address: %p\\n&quot;, (void *)p);</span></span>
<span class="line"><span>    printf(&quot;Value through pointer: %d\\n&quot;, *p);</span></span>
<span class="line"><span>    *p = 20;</span><span>  // modify the value via the pointer</span></span>
<span class="line"><span>    printf(&quot;New value of number: %d\\n&quot;, number);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译并运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc pointer_basics.c -o pointer_basics</span></span>
<span class="line"><span>./pointer_basics</span></span></code></pre></div><p>输出（地址不同）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Value of number: 10</span></span>
<span class="line"><span>Address of number: 0x7ffc8f4c9c4c</span></span>
<span class="line"><span>Pointer p holds address: 0x7ffc8f4c9c4c</span></span>
<span class="line"><span>Value through pointer: 10</span></span>
<span class="line"><span>New value of number: 20</span></span></code></pre></div><h4 id="指针声明和解除引用" tabindex="-1">指针声明和解除引用 <a class="header-anchor" href="#指针声明和解除引用" aria-label="Permalink to &quot;指针声明和解除引用&quot;">​</a></h4><table tabindex="0"><thead><tr><th>语法</th><th>意义</th></tr></thead><tbody><tr><td><code>int *p;</code></td><td>指向整数的指针</td></tr><tr><td><code>char *c;</code></td><td>指向字符的指针</td></tr><tr><td><code>float *f;</code></td><td>指向浮点数的指针</td></tr><tr><td><code>p = &amp;x;</code></td><td>分配变量的地址<code>x</code>到指针<code>p</code></td></tr><tr><td><code>*p</code></td><td>访问（取消引用）存储在地址中的值<code>p</code></td></tr></tbody></table><p>解除引用有两种作用：</p><ul><li>读取值：<code>x = *p;</code></li><li>写入地址：<code>*p = 99;</code></li></ul><h4 id="空指针" tabindex="-1">空指针 <a class="header-anchor" href="#空指针" aria-label="Permalink to &quot;空指针&quot;">​</a></h4><p>一个不指向任何东西的指针应该被设置为<code>NULL</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int *ptr = NULL;</span></span>
<span class="line"><span>if (ptr == NULL) {</span></span>
<span class="line"><span>    printf(&quot;Pointer is not initialized.\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>取消引用空指针（<code>*ptr</code>什么时候<code>ptr == NULL</code>）导致分段错误，这是最常见的 C 错误之一。</p><h4 id="指针到指针" tabindex="-1">指针到指针 <a class="header-anchor" href="#指针到指针" aria-label="Permalink to &quot;指针到指针&quot;">​</a></h4><p>您可以使用存储其他指针地址的指针。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int x = 5;</span></span>
<span class="line"><span>int *p = &amp;x;</span></span>
<span class="line"><span>int **pp = &amp;p;</span></span>
<span class="line"><span>printf(&quot;x = %d\\n&quot;, **pp);</span></span></code></pre></div><p>这个概念出现在多维数组和函数指针中。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>指针使 C 变得强大：</p><ul><li>它们启用动态内存分配（<code>malloc</code>,<code>calloc</code>,<code>free</code>).</li><li>它们允许有效地传递数组、字符串和结构。</li><li>它们是链表、树和系统调用的基础。</li></ul><p>但他们也要求精度。单个误用的指针可能会导致崩溃或内存损坏。</p><p>掌握指针意味着掌握对内存的控制和责任。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>编写一个程序，声明一个整数并打印它的值和地址。</li><li>创建一个指向该整数的指针，并通过该指针修改变量的值。 3.尝试声明<code>int *p = NULL;</code>并在取消引用之前检查它。</li><li>打印一个指向指针的指针（<code>int **</code>）并查看地址如何关联。</li><li>为了好玩，声明两个变量并使用解引用使一个指针交换它们的值。</li></ol><p>一旦你真正理解了指针，C 的其余部分、数组、结构、动态内存，甚至函数调用，就开始有意义了。它们是代码和机器实际内存之间的桥梁。</p>`,33)])])}const b=s(p,[["render",i]]);export{u as __pageData,b as default};
